document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll("input[data-unit]"),t={mm:1e3,cm:100,m:1,km:.001,in:39.37007874,ft:3.280839895,yd:1.093613298,mi:621371e-9};function n(n,s){if(s===""||isNaN(s)){e.forEach(e=>e.value="");return}const o=s/t[n];e.forEach(e=>{const s=e.dataset.unit;if(s!==n){const n=o*t[s];e.value=parseFloat(n.toFixed(6))}})}e.forEach(e=>{e.addEventListener("input",e=>{n(e.target.dataset.unit,parseFloat(e.target.value))})})})